exercise.solution:
def arguments_calcul(args):
    if not isinstance(args,dict) or set(args)!={'expression'} or not isinstance(args['expression'],str):raise ValueError('arguments invalides')
    return dict(args)

exercise.check:
assert arguments_calcul({'expression':'1+2'})=={'expression':'1+2'}
for x in [{'expression':3},{'expression':'1','shell':True},[]]:
    try:arguments_calcul(x)
    except ValueError:pass
    else:raise AssertionError('arguments invalides acceptés')
